async function oEmbedTitle(v){if(v.host!=='youtube'&&v.host!=='vimeo')return null;const o=v.host==='youtube'?'https://www.youtube.com/oembed?url='+encodeURIComponent(v.url)+'&format=json':'https://vimeo.com/api/oembed.json?url='+encodeURIComponent(v.url);try{const r=await fetch(o);if(!r.ok)return null;const d=await r.json();return d.title||null;}catch(e){return null;}}
const BREAKDOWN_WORDS=['brkd','breakdown','breakdowns','making','mof','bts','wip','showcase','showcases','progression','process','processes','progress','turnaround','turnarounds','turntable','turntables','turn','lookdev','lookdevs','reel','reels','rig','rigs','rigging','rigg','test','tests','testing','shot','shots','character','characters','environment','environments','render','renders','rendering','compositing','comp','fx','lighting','blocking','block','blocks','demo','demos','comparison','quad','orchestra','layout','layouts','pipeline','cfx','procedural','blendshape','blendshapes','expression','expressions','cycle','simulation','simulations','hair','clothes','cloth','frame','frames','storyboard','blockout'];
function classify(video,workTitle){if(video.host==='direct')return 'other';const t=(video.title||'').toLowerCase();const w=(workTitle||'').toLowerCase();if(!t)return 'locked';const tn=t.replace(/[^a-z0-9]+/g,' ').trim().replace(/\b(making[ -]?of|behind[ -]?the[ -]?scenes)\b/g,' breakdown ');for(const word of BREAKDOWN_WORDS){if(new RegExp('(?<![a-z0-9])'+word+'(?![a-z0-9])').test(tn))return 'breakdown';}if(/\b(short film|teaser|trailer|official|officielle|bande[ -]annonce|court[ -]m[eé]trage|the movie|full movie|full film|full|movie|film)\b/.test(tn))return 'main';const core=w.replace(/\s*[-–|].+$/,'').replace(/\b(the|a|short film|film|movie|2025|2026)\b/g,'').replace(/[^a-z0-9]+/g,' ').trim();if(core&&core.length>=3&&tn.includes(core))return 'main';return 'other';}
function parseEntry(html,selfId){const doc=new DOMParser().parseFromString(html,'text/html');const og=doc.querySelector('meta[property="og:title"]')?.content||'';let title=og.replace(/^The Rookies - /,'');let author='';const byM=title.match(/, by (.+)$/);if(byM){author=byM[1].split(', by ')[0];title=title.replace(/, by .+$/,'');}const avatar=doc.querySelector('.project-header img.avatar-media, .project-content img.avatar-media, main img.avatar-media')?.alt?.trim();if(avatar&&author.toLowerCase()!==avatar.toLowerCase())author=avatar;const videos=[];const images=[];const linkedEntries=[];const pc=doc.querySelector('.project-content');if(pc){const sections=[];const walker=document.createTreeWalker(pc,NodeFilter.SHOW_ELEMENT);let lastH3='';while(walker.nextNode()){const n=walker.currentNode;if(n.tagName==='H3')lastH3=n.innerText.trim().replace(/\s+/g,' ');if(n.tagName==='IFRAME')sections.push({node:n,section:lastH3});}for(const{node:el,section}of sections){const s=el.src||'';if(s.includes('youtube.com/embed/'))videos.push({host:'youtube',url:'https://www.youtube.com/watch?v='+s.split('/embed/')[1].split('?')[0],section,title:null});else if(s.includes('vimeo.com'))videos.push({host:'vimeo',url:s.split('?')[0],section,title:null});}for(const v of pc.querySelectorAll(':scope video')){const src=v.currentSrc||v.getAttribute('src')||'';if(src)videos.push({host:'direct',url:src,section:'',title:null});for(const s of v.querySelectorAll('source')){if(s.src)videos.push({host:'direct',url:s.src,section:'',title:null});}}for(const a of pc.querySelectorAll(':scope a[href*="/entries/"]')){const m=a.href.match(/\/entries\/(\d+)/);if(m&&m[1]!==String(selfId)){linkedEntries.push({id:m[1],label:(a.innerText||'').trim().slice(0,60)||a.href});}}for(const img of pc.querySelectorAll(':scope img')){if(img.src&&img.src.includes('cloudfront')){images.push(img.src.replace(/\/([0-9]+)xAUTO\//,'/3840xAUTO/'));}}}return{title,author,videos,images,linkedEntries};}
return (async()=>{const selfId="48448";const r=parseEntry(document.documentElement.outerHTML,selfId);const results=[r];return results;})();